        np.testing.assert_allclose(np.triu(A, 1), 0, atol=1e-12)
        np.testing.assert_allclose(A.sum(-1), 1)
        np.testing.assert_allclose(out, [[2, 0], [1.6351, 0.5474], [1.3856, 1.9345]], atol=1e-3)

