def layer_norm(x, eps=1e-5):
    """Normaliza cada fila a media cero y varianza aproximadamente uno."""
    x = np.asarray(x)
    media = np.mean(x, axis=-1, keepdims=True)
    varianza = np.mean((x - media) ** 2, axis=-1, keepdims=True)
    return (x - media) / np.sqrt(varianza + eps)

def month_cyclical(month_series):
    """MonthSold (1-12) -> (seno, coseno): la codificación cíclica correcta."""
    radians = 2 * np.pi * month_series.to_numpy(dtype=float) / 12
    return np.column_stack([np.sin(radians), np.cos(radians)])

def _normalizar(m):
    return m / np.linalg.norm(m, axis=1, keepdims=True).clip(min=1e-12)


class BertPromedio:
    """Linea de base obligatoria: BERT sin ajustar para similitud, embedding = promedio de los
    vectores de la ultima capa sobre los tokens reales (se ignora el padding)."""

    def __init__(self, modelo="google-bert/bert-base-multilingual-cased", lote=16):
        from transformers import AutoModel, AutoTokenizer

        self.nombre, self.lote = modelo, lote
        self.tokenizer = AutoTokenizer.from_pretrained(modelo)
        self.modelo = AutoModel.from_pretrained(modelo).eval()

    def _codificar(self, textos):
        import torch

        salidas = []
        with torch.no_grad():
            for i in range(0, len(textos), self.lote):
                enc = self.tokenizer(textos[i:i + self.lote], padding=True, truncation=True,
                                     max_length=512, return_tensors="pt")
                h = self.modelo(**enc).last_hidden_state
                m = enc["attention_mask"].unsqueeze(-1).float()
                salidas.append(((h * m).sum(1) / m.sum(1)).numpy())
        return _normalizar(np.concatenate(salidas))

    codificar_consultas = codificar_pasajes = _codificar

class SentenceTransformerEncoder:
    """Modelos entrenados para embeddings de oraciones (MiniLM, e5, bge-m3). Los e5 piden prefijos."""

    def __init__(self, modelo, prefijo_consulta="", prefijo_pasaje="", lote=16):
        from sentence_transformers import SentenceTransformer

        self.nombre, self.lote = modelo, lote
        self.prefijo_consulta, self.prefijo_pasaje = prefijo_consulta, prefijo_pasaje
        self.modelo = SentenceTransformer(modelo, device="cpu")

    def _codificar(self, textos, prefijo):
        m = self.modelo.encode([prefijo + t for t in textos], batch_size=self.lote,
                               normalize_embeddings=True, show_progress_bar=False)
        return np.asarray(m, dtype=np.float32)

    def codificar_consultas(self, textos):
        return self._codificar(textos, self.prefijo_consulta)

    def codificar_pasajes(self, textos):
        return self._codificar(textos, self.prefijo_pasaje)


def crear_encoder(cfg):
    """cfg: {"tipo": "bert_promedio" | "sentence_transformer", "modelo": ..., "prefijo_consulta": ..., "prefijo_pasaje": ...}"""
    if cfg["tipo"] == "bert_promedio":
        return BertPromedio(cfg["modelo"])
    if cfg["tipo"] == "sentence_transformer":
        return SentenceTransformerEncoder(cfg["modelo"], cfg.get("prefijo_consulta", ""), cfg.get("prefijo_pasaje", ""))
    raise ValueError(f"tipo de encoder desconocido: {cfg['tipo']}")

def tokenizar_conversacion(registro, tokenizer, max_seq_length):
    """Incluye respuesta y cierre del turno; excluye encabezados y todo contexto.

    Solo acepta plantillas/tokenizadores que preserven exactamente sus prefijos.
    No pide máscaras nativas (Gemma fijado no tiene bloques generation).
    """
    validar_registro(registro)
    if type(max_seq_length) is not int or max_seq_length <= 0:
        raise ValueError("max_seq_length requiere entero positivo")
    mensajes = registro["messages"]

    def tokens(historia, generar=False):
        salida = tokenizer.apply_chat_template(
            historia, tokenize=True, add_generation_prompt=generar,
            enable_thinking=False, padding=False, truncation=False, return_dict=True)
        ids = salida["input_ids"]
        if not isinstance(ids, list) or not ids or any(type(x) is not int or x < 0 for x in ids):
            raise ValueError("tokenizador devolvió IDs inválidos o anidados")
        if salida.get("attention_mask", [1] * len(ids)) != [1] * len(ids):
            raise ValueError("tokenización individual no debe contener padding")
        return ids

    ids = tokens(mensajes)
    if len(ids) > max_seq_length:
        raise ValueError("conversación excede max_seq_length; no se recorta")
    labels = [-100] * len(ids)
    for i, mensaje in enumerate(mensajes):
        if mensaje["role"] != "assistant":
            continue
        inicio = tokens(mensajes[:i], True)
        fin = tokens(mensajes[:i + 1])
        if ids[:len(inicio)] != inicio or ids[:len(fin)] != fin or len(fin) <= len(inicio):
            raise ValueError("plantilla/tokenizador no preserva prefijos; máscara insegura")
        labels[len(inicio):len(fin)] = ids[len(inicio):len(fin)]
    if all(x == -100 for x in labels):
        raise ValueError("conversación sin tokens supervisados")
    return {"input_ids": ids, "attention_mask": [1] * len(ids), "labels": labels}
